static char *
strsep_char(char *strp, char delim)
{
    char *ptr;

    if (UNLIKELY(!strp))
        return NULL;

    ptr = strchr(strp, delim);
    if (UNLIKELY(!ptr))
        return NULL;

    *ptr = '\0';
    return ptr + 1;
}

static char *
